const livro = { titulo: 'Dom Casmurro', autor: 'Machado de Assis', paginas: 256 };

console.log('Título:', livro.titulo);
console.log('Autor:', livro.autor);
console.log('Páginas:', livro.paginas);

const compra = { fruta: 'Manga', precoDoQuilo: 6, quilos: 3 };

console.log(compra.fruta + ':', compra.quilos, 'kg');
console.log('Preço do quilo:', compra.precoDoQuilo);
console.log('Total a pagar:', compra.precoDoQuilo * compra.quilos);

const cartao = { dono: 'Rita', saldo: 40, passagem: 5, ativo: true };

console.log('Cartão de ' + cartao.dono);
console.log('Saldo:', cartao.saldo);
console.log('Viagens possíveis:', cartao.saldo / cartao.passagem);
console.log('Ativo:', cartao.ativo);

